namespace ks {namespace {PartEnablePartialTest partialTest=nullptr;using S=PartEnableTask::Stage;using R=PartEnableTask::Read;using W=PartEnableTask::Write;struct Point{unsigned location,length;};Point point(S s){switch(s){case S::SelectPart:return {0x9f28,6};case S::DispatchControl:return {0x9f2e,4};case S::AwaitControl:case S::Enable:return {0x9f32,2};case S::WriteEnable:return {0x9f34,8};case S::ReadGeneration:return {0x9f3c,8};case S::BumpGeneration:return {0x9f44,2};case S::WriteGeneration:return {0x9f46,8};case S::Finish:return {0x9f4e,2};default:throw std::runtime_error("Invalid part enable stage");}}}
bool PartEnableCalls::step(ControllerCpu&h){using namespace controllerDetail;unsigned pc=unsigned(h.getPC());std::optional<Call>*selected=nullptr;for(auto&c:calls)if(c&&c->token==h.getSP()){selected=&c;break;}if(pc==0x9f28){if(selected)throw std::runtime_error("Overlapping part enable");for(auto&c:calls)if(!c){selected=&c;break;}if(!selected)throw std::runtime_error("Part enable capacity");selected->emplace(h.getSP());++started;}if(!selected||point((**selected).task.stage()).location!=pc){if(partialTest&&partialTest(h)){++partialEntries;return true;}return false;}auto&t=(**selected).task;auto&v=h.regs;if(t.awaiting()){auto ptr=uint32_t(v[0].er);if(ptr<0x174ae||ptr>=0x174ae + 20*256||(ptr-0x174ae)%20)throw std::runtime_error("Invalid enable control binding");t.resumeChild(uint8_t((ptr-0x174ae)/20));}auto stage=t.stage();auto before=h.cycles;Boundary f(h,pc,point(stage).length);auto control=0x174aeu+20*t.part();auto address=[&](W w){return w==W::Part?0x17526u:control+(w==W::Enable?17:18);};auto store=[&](W w){auto at=address(w);return (at&1)&&h.lastwrite==int(at-1)?0u:3u;};auto cost=t.nextClocks(store);t.advanceBefore(cost,[&](R r)->uint8_t{return r==R::Input?uint8_t(v[6].rl):uint8_t(h.read8(control+18));},[&](W w,uint8_t value){f.store8(address(w),int8_t(value));},store);switch(stage){case S::DispatchControl:f.call(0xa66a);h.pc=h.makepc(f.next);break;case S::Enable:f.move(v[6].rl,1);break;case S::ReadGeneration:f.move(v[6].rl,t.generation());break;case S::BumpGeneration:v[6].rl=h.add8(v[6].rl,8);break;case S::Finish:f.ret();h.pc=h.makepc(f.next);selected->reset();++completed;break;default:break;}if(stage!=S::DispatchControl&&stage!=S::Finish)h.pc=h.makepc(point(t.stage()).location);if(h.cycles-before!=cost)throw std::runtime_error("Part enable clocks differ");return true;}}

